const r = $json.choices?.[0]?.message?.content || '';
const m = r.match(/\{[\s\S]*\}/);
if (!m) throw new Error('no JSON');
const parsed = JSON.parse(m[0]);
// Normalize to intent_class for backend compatibility
const category = (parsed.category || parsed.intent_class || 'unknown').toUpperCase();
const CATEGORY_MAP = {
  'POSITIVE': 'INTERESTED', 'INTERESTED': 'INTERESTED', 'MEETING_REQUEST': 'BOOKING_REQUEST',
  'QUESTION': 'QUESTION', 'PRICING': 'PRICE', 'NOT_NOW': 'HUMAN_REQUIRED',
  'REFERRAL': 'HUMAN_REQUIRED', 'UNSUBSCRIBE': 'NOT_INTERESTED', 'NEGATIVE': 'NOT_INTERESTED',
  'WRONG_PERSON': 'HUMAN_REQUIRED', 'OUT_OF_OFFICE': 'HUMAN_REQUIRED',
  'AUTOMATIC_REPLY': 'HUMAN_REQUIRED', 'UNKNOWN': 'HUMAN_REQUIRED',
};
return {
  llm: {
    intent_class: CATEGORY_MAP[category] || 'HUMAN_REQUIRED',
    category: category,
    confidence: parsed.confidence || 0.5,
    suggested_response: parsed.suggested_response || null,
    escalation_needed: ['POSITIVE', 'INTERESTED', 'MEETING_REQUEST', 'NOT_NOW', 'REFERRAL', 'WRONG_PERSON'].includes(category),
  },
  usage: $json.usage || {}
};
